{
  "containers": [
    {
      "args": [
        "while true; do\n  if wget -q -O - -T 3 \"http://$PEER_HOST/\" 2>/dev/null | grep -q \"Welcome to nginx!\"; then\n    echo ok > /shared/status\n  else\n    echo fail > /shared/status\n  fi\n  sleep 2\ndone\n"
      ],
      "command": [
        "sh",
        "-c"
      ],
      "env": [
        {
          "name": "PEER_HOST",
          "value": "peer.prod"
        }
      ],
      "image": "busybox:1.37.0",
      "imagePullPolicy": "IfNotPresent",
      "name": "client",
      "readinessProbe": {
        "exec": {
          "command": [
            "sh",
            "-c",
            "grep -q ok /shared/status"
          ]
        },
        "failureThreshold": 3,
        "initialDelaySeconds": 3,
        "periodSeconds": 3,
        "successThreshold": 1,
        "timeoutSeconds": 1
      },
      "resources": {},
      "terminationMessagePath": "/dev/termination-log",
      "terminationMessagePolicy": "File",
      "volumeMounts": [
        {
          "mountPath": "/shared",
          "name": "shared"
        }
      ]
    }
  ],
  "dnsPolicy": "ClusterFirst",
  "restartPolicy": "Always",
  "schedulerName": "default-scheduler",
  "securityContext": {},
  "terminationGracePeriodSeconds": 30,
  "volumes": [
    {
      "emptyDir": {},
      "name": "shared"
    }
  ]
}
---
